/**
 * Returns the price the caller would be charged today for a single
serve at the given service type. Drives the live price card on the
attorney's Post-a-Job form. The price is derived from the caller's
active ProServe subscription (if any) so subscribers see their
discounted rate immediately.

 * @summary Live per-serve price for the caller's tier and the requested service type
 */
export const getGetServePricePreviewUrl = (
  params: GetServePricePreviewParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/pricing/serve-preview?${stringifiedParams}`
    : `/api/pricing/serve-preview`;
};

export const getServePricePreview = async (
  params: GetServePricePreviewParams,
  options?: RequestInit,
): Promise<ServePricePreview> => {
  return customFetch<ServePricePreview>(getGetServePricePreviewUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetServePricePreviewQueryKey = (
  params?: GetServePricePreviewParams,
) => {
  return [`/api/pricing/serve-preview`, ...(params ? [params] : [])] as const;
};

export const getGetServePricePreviewQueryOptions = <
  TData = Awaited<ReturnType<typeof getServePricePreview>>,
  TError = ErrorType<unknown>,
>(
  params: GetServePricePreviewParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getServePricePreview>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetServePricePreviewQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getServePricePreview>>
  > = ({ signal }) =>
    getServePricePreview(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getServePricePreview>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetServePricePreviewQueryResult = NonNullable<
  Awaited<ReturnType<typeof getServePricePreview>>
>;
export type GetServePricePreviewQueryError = ErrorType<unknown>;

/**
 * @summary Live per-serve price for the caller's tier and the requested service type
 */

export function useGetServePricePreview<
  TData = Awaited<ReturnType<typeof getServePricePreview>>,
  TError = ErrorType<unknown>,
>(
  params: GetServePricePreviewParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getServePricePreview>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetServePricePreviewQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

